def render_internal(case: tuple[str, ...]) -> str:
    complaint, history, past, allergy, exam, ancillary, diagnosis, plan = case
    return (
        f"主诉是{complaint}。{history}。既往史方面，{past}。过敏史方面，{allergy}。"
        f"体格检查：{exam}。辅助检查：{ancillary}。初步考虑{diagnosis}。"
        f"处理意见为{plan}。"
    )


def render_emergency(case: dict[str, str], index: int) -> str:
    parts = ["急诊口述，先记一下，信息按到达顺序记录。"]
    if "disposition" in case:
        parts.append(f"去向先说，拟{case['disposition']}，后面再补检查。")
    parts.append(f"刚复测生命体征，{case['v2']}。等一下，先问病史——{case['history']}。")
    if "time" in case:
        parts.append(f"到诊时间是{case['time']}。")
    parts.append(f"主诉整理成{case['complaint']}。有人打断了，继续。查体{case['exam']}。")
    if "allergy" in case:
        parts.append(f"过敏情况：{case['allergy']}。")
    parts.append(f"最初生命体征其实是{case['v1']}，以最初值入记录。")
    parts.append(f"检查回来，{case['test']}。考虑{case['diagnosis']}。")
    if "treatment" in case:
        parts.append(f"处置补记：{case['treatment']}。")
    parts.append("以上均为本次虚构演示口述。")
    if index % 3 == 0:
        parts.insert(2, "电话响了——稍等——现在接着记。")
    return "\n".join(parts)


def main() -> None:
    OUTPUT.mkdir(parents=True, exist_ok=True)
    for index, case in enumerate(INTERNAL_CASES, start=1):
        (OUTPUT / f"im_{index:02d}.txt").write_text(render_internal(case) + "\n", encoding="utf-8")
    for index, case in enumerate(EMERGENCY_CASES, start=1):
        (OUTPUT / f"em_{index:02d}.txt").write_text(render_emergency(case, index) + "\n", encoding="utf-8")
    print(f"Wrote {len(INTERNAL_CASES) + len(EMERGENCY_CASES)} fictional dictations to {OUTPUT}")


if __name__ == "__main__":
    main()
